31: @RequiresApi(26)
32: public final class StreamingTranscoder {
33: 
34:   private static final String TAG = Log.tag(StreamingTranscoder.class);
35: 
36:   private final           MediaDataSource    dataSource;
37:   private final           long               upperSizeLimit;
38:   private final           long               inSize;
39:   private final           long               duration;
40:   private final           int                inputBitRate;
41:   private final           TranscodingQuality targetQuality;
42:   private final           boolean            transcodeRequired;
43:   private final           long               fileSizeEstimate;
44:   private final @Nullable TranscoderOptions  options;
45:   private final           boolean            allowAudioRemux;
46:   private final           boolean            skipAudio;
47: 
48:   /**
49:    * @param upperSizeLimit A upper size to transcode to. The actual output size can be up to 10% smaller.
50:    */
51:   public StreamingTranscoder(@NonNull MediaDataSource dataSource,
52:                              @Nullable TranscoderOptions options,
53:                              @NonNull List<TranscodingConfig.QualityTier> configs,
54:                              long upperSizeLimit,
55:                              boolean allowAudioRemux)
56:       throws IOException, VideoSourceException
57:   {
58:     this.dataSource = dataSource;
59:     this.options    = options;
60:     this.allowAudioRemux = allowAudioRemux;
61:     this.skipAudio  = options != null && options.skipAudio;
62: 
63:     final MediaMetadataRetriever mediaMetadataRetriever = new MediaMetadataRetriever();
64:     try {
65:       mediaMetadataRetriever.setDataSource(dataSource);
66:     } catch (RuntimeException e) {
67:       Log.w(TAG, "Unable to read datasource", e);
68:       throw new VideoSourceException("Unable to read datasource", e);
69:     }
70: 
71:     if (options != null && options.endTimeUs != 0) {
72:       this.duration = TimeUnit.MICROSECONDS.toMillis(options.endTimeUs - options.startTimeUs);
73:     } else {
74:       this.duration = getDuration(mediaMetadataRetriever);
75:     }
76: 
77:     this.inSize         = dataSource.getSize();
78:     this.inputBitRate   = TranscodingQuality.bitRate(inSize, duration);
79:     this.targetQuality  = TranscodingQuality.createFromQualityTiers(configs, duration);
80:     this.upperSizeLimit = upperSizeLimit;
81: 
82:     this.transcodeRequired = inputBitRate >= targetQuality.getTargetTotalBitRate() * 1.2 || inSize > upperSizeLimit || containsLocation(mediaMetadataRetriever) || options != null || skipAudio || !isH264(dataSource);
83:     if (!transcodeRequired) {
84:       Log.i(TAG, "Video is within 20% of target bitrate, below the size limit, contained no location metadata or custom options, and is already H.264.");
85:     }
86: 
87:     if (skipAudio) {
88:       Log.i(TAG, "Audio was removed by the user, so the video track has to be written out again without it.");
89:     }
90: 
91:     this.fileSizeEstimate   = targetQuality.getByteCountEstimate();
92:   }
93: 
94:   private StreamingTranscoder(@NonNull MediaDataSource dataSource,
95:                              @Nullable TranscoderOptions options,
96:                              String codec,
97:                              int videoBitrate,
98:                              int audioBitrate,
99:                              int shortEdge,
100:                              boolean allowAudioRemux)
101:       throws IOException, VideoSourceException
102:   {
103:     this.dataSource      = dataSource;
104:     this.options         = options;
105:     this.allowAudioRemux = allowAudioRemux;
106:     this.skipAudio       = options != null && options.skipAudio;
107: 
108:     final MediaMetadataRetriever mediaMetadataRetriever = new MediaMetadataRetriever();
109:     try {
110:       mediaMetadataRetriever.setDataSource(dataSource);
111:     } catch (RuntimeException e) {
112:       Log.w(TAG, "Unable to read datasource", e);
113:       throw new VideoSourceException("Unable to read datasource", e);
114:     }
115: 
116:     this.inSize         = dataSource.getSize();
117:     this.duration       = getDuration(mediaMetadataRetriever);
118:     this.inputBitRate   = TranscodingQuality.bitRate(inSize, duration);
119:     this.targetQuality  = TranscodingQuality.createManuallyForTesting(codec, shortEdge, videoBitrate, audioBitrate, duration);
120:     this.upperSizeLimit = 0L;
121: 
122:     this.transcodeRequired = true;
123: 
124:     this.fileSizeEstimate   = targetQuality.getByteCountEstimate();
125:   }
126: 
127:   @VisibleForTesting
128:   public static StreamingTranscoder createManuallyForTesting(@NonNull MediaDataSource dataSource,
129:                                                              @Nullable TranscoderOptions options,
130:                                                              @NonNull @MediaConverter.VideoCodec String codec,
131:                                                              int videoBitrate,
132:                                                              int audioBitrate,
133:                                                              int shortEdge,
134:                                                              boolean allowAudioRemux)
135:       throws VideoSourceException, IOException
136:   {
137:     return new StreamingTranscoder(dataSource, options, codec, videoBitrate, audioBitrate, shortEdge, allowAudioRemux);
138:   }
139: 
140:   /**
141:    * @return The total content size of the MP4 mdat box.
142:    */
143:   public long transcode(@NonNull Progress progress,
144:                         @NonNull OutputStream stream,
145:                         @Nullable TranscoderCancelationSignal cancelationSignal)
146:       throws IOException, EncodingException
147:   {
148:     float durationSec = duration / 1000f;
149: 
150:     NumberFormat numberFormat = NumberFormat.getInstance(Locale.US);
151: 
152:     Log.i(TAG, String.format(Locale.US,
153:                              "Transcoding:\n" +
154:                              "Target bitrate : %s + %s = %s\n" +
155:                              "Target format  : %dp\n" +
156:                              "Video duration : %.1fs\n" +
157:                              "Size limit     : %s kB\n" +
158:                              "Estimate       : %s kB\n" +
159:                              "Input size     : %s kB\n" +
160:                              "Input bitrate  : %s bps",
161:                              numberFormat.format(targetQuality.getTargetVideoBitRate()),
162:                              numberFormat.format(targetQuality.getTargetAudioBitRate()),
163:                              numberFormat.format(targetQuality.getTargetTotalBitRate()),
164:                              targetQuality.getOutputResolution(),
165:                              durationSec,
166:                              numberFormat.format(upperSizeLimit / 1024),
167:                              numberFormat.format(fileSizeEstimate / 1024),
168:                              numberFormat.format(inSize / 1024),
169:                              numberFormat.format(inputBitRate)));
170: 
171:     final boolean sizeLimitEnabled = 0 < upperSizeLimit;
172: 
173:     if (sizeLimitEnabled && upperSizeLimit < fileSizeEstimate) {
174:       throw new VideoSizeException("Size constraints could not be met! upperSizeLimit: " + upperSizeLimit + ", fileSizeEstimate: " + fileSizeEstimate);
175:     }
176: 
177:     final long startTime = System.currentTimeMillis();
178: 
179:     final MediaConverter converter = new MediaConverter();
180: 
181:     converter.setInput(new MediaDataSourceMediaInput(dataSource));
182:     final CountingOutputStream outStream;
183:     if (sizeLimitEnabled) {
184:       outStream = new CountingOutputStream(new LimitedSizeOutputStream(stream, upperSizeLimit));
185:     } else {
186:       outStream = new CountingOutputStream(stream);
187:     }
188:     converter.setOutput(outStream);
189:     converter.setVideoCodec(targetQuality.getCodec());
190:     converter.setVideoResolution(targetQuality.getOutputResolution());
191:     converter.setVideoBitrate(targetQuality.getTargetVideoBitRate());
192:     converter.setAudioBitrate(targetQuality.getTargetAudioBitRate());
193:     converter.setAllowAudioRemux(allowAudioRemux);
194: 
195:     if (options != null) {
196:       if (options.endTimeUs > 0) {
197:         long timeFrom = options.startTimeUs / 1000;
198:         long timeTo   = options.endTimeUs   / 1000;
199:         converter.setTimeRange(timeFrom, timeTo);
200:         Log.i(TAG, String.format(Locale.US, "Trimming:\nTotal duration: %d\nKeeping: %d..%d\nFinal duration:(%d)", duration, timeFrom, timeTo, timeTo - timeFrom));
201:       }
202:     }
203: 
204:     // Always stated explicitly, so a video that keeps its audio can never inherit a previous run's skip flag. Only
205:     // the audio track is dropped: the video track is what the user asked to send, and it is always retained.
206:     converter.setSkipAudio(skipAudio);
207: 
208:     converter.setListener(percent -> {
209:       progress.onProgress(percent);
210:       return cancelationSignal != null && cancelationSignal.isCanceled();
211:     });
212: 
213:     long mdatSize = converter.convert();
214: 
215:     long  outSize           = outStream.getCount();
216:     float encodeDurationSec = (System.currentTimeMillis() - startTime) / 1000f;
217: 
218:     Log.i(TAG, String.format(Locale.US,
219:                              "Transcoding complete:\n" +
220:                              "Transcode time : %.1fs (%.1fx)\n" +
221:                              "Output size    : %s kB\n" +
222:                              "  of Original  : %.1f%%\n" +
223:                              "  of Estimate  : %.1f%%\n" +
224:                              "Output bitrate : %s bps",
225:                              encodeDurationSec,
226:                              durationSec / encodeDurationSec,
227:                              numberFormat.format(outSize / 1024),
228:                              (outSize * 100d) / inSize,
229:                              (outSize * 100d) / fileSizeEstimate,
230:                              numberFormat.format(TranscodingQuality.bitRate(outSize, duration))));
231: 
232:     if (sizeLimitEnabled && outSize > upperSizeLimit) {
233:       throw new VideoSizeException("Size constraints could not be met!");
234:     }
235: 
236:     stream.flush();
237: 
238:     return mdatSize;
239:   }
