241:   public boolean isTranscodeRequired() {
242:     return transcodeRequired;
243:   }
244: 
245:   /** Whether this transcode drops the audio track while keeping the video track. */
246:   public boolean isSkipAudio() {
247:     return skipAudio;
248:   }
