250:   private static long getDuration(MediaMetadataRetriever mediaMetadataRetriever) throws VideoSourceException {
251:     String durationString = mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);
252:     if (durationString == null) {
253:       throw new VideoSourceException("Cannot determine duration of video, null meta data");
254:     }
255:     try {
256:       long duration = Long.parseLong(durationString);
257:       if (duration <= 0) {
258:         throw new VideoSourceException("Cannot determine duration of video, meta data: " + durationString);
259:       }
260:       return duration;
261:     } catch (NumberFormatException e) {
262:       throw new VideoSourceException("Cannot determine duration of video, meta data: " + durationString, e);
263:     }
264:   }
265: 
266:   private static boolean containsLocation(MediaMetadataRetriever mediaMetadataRetriever) {
267:     String locationString = mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_LOCATION);
268:     return locationString != null;
269:   }
270: 
271:   private static boolean isH264(@NonNull MediaDataSource dataSource) {
272:     MediaExtractor extractor = new MediaExtractor();
273:     try {
274:       extractor.setDataSource(dataSource);
275:       for (int i = 0; i < extractor.getTrackCount(); i++) {
276:         MediaFormat format = extractor.getTrackFormat(i);
277:         String mime = format.getString(MediaFormat.KEY_MIME);
278:         if (mime != null && mime.startsWith("video/")) {
279:           return MediaConverter.VIDEO_CODEC_H264.equals(mime);
280:         }
281:       }
282:       return false;
283:     } catch (IOException e) {
284:       Log.w(TAG, "Unable to check video codec", e);
285:       return false;
286:     } finally {
287:       extractor.release();
288:     }
289:   }
290: 
291:   public interface Progress {
292:     void onProgress(int percent);
293:   }
