295:   private static class LimitedSizeOutputStream extends FilterOutputStream {
296: 
297:     private final long sizeLimit;
298:     private       long written;
299: 
300:     LimitedSizeOutputStream(@NonNull OutputStream inner, long sizeLimit) {
301:       super(inner);
302:       this.sizeLimit = sizeLimit;
303:     }
304: 
305:     @Override public void write(int b) throws IOException {
306:       incWritten(1);
307:       out.write(b);
308:     }
309: 
310:     @Override public void write(byte[] b, int off, int len) throws IOException {
311:       incWritten(len);
312:       out.write(b, off, len);
313:     }
314: 
315:     private void incWritten(int len) throws IOException {
316:       long newWritten = written + len;
317:       if (newWritten > sizeLimit) {
318:         Log.w(TAG, String.format(Locale.US, "File size limit hit. Wrote %d, tried to write %d more. Limit is %d", written, len, sizeLimit));
319:         throw new VideoSizeException("File size limit hit");
320:       }
321:       written = newWritten;
322:     }
323:   }
324: }

